html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, 'Segoe UI',
    Inter, Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;

  /* Light is the starting look for the page. */
  background: #f4f5f7;
  color: #14161a;
  transition: background-color 120ms linear, color 120ms linear;
}

body[data-theme='dark'] {
  background: #0a0b0d;
  color: #f3f5f8;
}

/* ---------------------------------------------------------------- tokens */

.app {
  --bg: #f4f5f7;
  --surface: #ffffff;
  --surface-alt: #ffffff;
  --text: #14161a;
  --text-muted: #5c6470;
  --border: #dfe3e8;
  --accent: #2f6df6;
  --accent-text: #ffffff;
  --shadow: 0 1px 2px rgba(16, 20, 28, 0.06),
    0 8px 24px rgba(16, 20, 28, 0.06);

  min-height: 100vh;
  width: 100%;
  background: var(--bg);
  color: var(--text);
  transition: background-color 120ms linear, color 120ms linear;
}

.app[data-theme='dark'] {
  --bg: #0a0b0d;
  --surface: #15181d;
  --surface-alt: #1b1f26;
  --text: #f3f5f8;
  --text-muted: #a2acba;
  --border: #2b313a;
  --accent: #6f9dff;
  --accent-text: #0a0b0d;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.5), 0 12px 32px rgba(0, 0, 0, 0.45);
}

/* ---------------------------------------------------------------- layout */

.shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 48px 24px 72px;
  display: flex;
  flex-direction: column;
  gap: 40px;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.brand-title {
  margin: 0;
  font-size: 34px;
  line-height: 1.15;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.brand-subtitle {
  margin: 6px 0 0;
  font-size: 15px;
  color: var(--text-muted);
}

/* ---------------------------------------------------------- theme toggle */

.theme-toggle {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 16px 24px;
  min-height: 60px;
  font: inherit;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--text);
  background: var(--surface);
  border: 2px solid var(--border);
  border-radius: 999px;
  box-shadow: var(--shadow);
  cursor: pointer;
  transition: background-color 120ms linear, border-color 120ms linear,
    transform 80ms ease, color 120ms linear;
}

.theme-toggle:hover {
  border-color: var(--accent);
}

.theme-toggle:active {
  transform: translateY(1px);
}

.theme-toggle:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.theme-toggle-icon {
  font-size: 20px;
  line-height: 1;
}

.theme-toggle-switch {
  width: 46px;
  height: 26px;
  flex: none;
  border-radius: 999px;
  background: var(--border);
  padding: 3px;
  display: flex;
  transition: background-color 120ms linear;
}

.theme-toggle-knob {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--surface);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
  transition: transform 140ms ease;
}

.theme-toggle[aria-pressed='true'] .theme-toggle-switch {
  background: var(--accent);
}

.theme-toggle[aria-pressed='true'] .theme-toggle-knob {
  transform: translateX(20px);
}

/* -------------------------------------------------------------- composer */

.main {
  display: flex;
  flex-direction: column;
  gap: 40px;
}

.composer {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.composer-label {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.composer-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.composer-input {
  flex: 1 1 260px;
  min-width: 0;
  padding: 14px 18px;
  font: inherit;
  font-size: 16px;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  transition: border-color 120ms linear, background-color 120ms linear,
    color 120ms linear;
}

.composer-input::placeholder {
  color: var(--text-muted);
}

.composer-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(47, 109, 246, 0.18);
}

.composer-button {
  flex: none;
  padding: 14px 26px;
  font: inherit;
  font-size: 16px;
  font-weight: 600;
  color: var(--accent-text);
  background: var(--accent);
  border: none;
  border-radius: 14px;
  cursor: pointer;
  transition: filter 120ms linear, transform 80ms ease;
}

.composer-button:hover {
  filter: brightness(1.06);
}

.composer-button:active {
  transform: translateY(1px);
}

.composer-button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

/* ----------------------------------------------------------------- notes */

.notes {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.notes-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.notes-title {
  margin: 0;
  font-size: 20px;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.notes-count {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  background: var(--surface-alt);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 2px 10px;
}

.empty {
  margin: 0;
  padding: 32px;
  text-align: center;
  color: var(--text-muted);
  background: var(--surface);
  border: 1px dashed var(--border);
  border-radius: 18px;
}

.note-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.note-card {
  padding: 18px 20px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 18px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: background-color 120ms linear, border-color 120ms linear;
}

.note-text {
  margin: 0;
  font-size: 16px;
  word-break: break-word;
}

.note-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.note-time {
  font-size: 13px;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.note-delete {
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 6px 14px;
  cursor: pointer;
  transition: color 120ms linear, border-color 120ms linear;
}

.note-delete:hover {
  color: var(--text);
  border-color: var(--accent);
}

.note-delete:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

/* ---------------------------------------------------------------- footer */

.footer {
  font-size: 13px;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
  padding-top: 20px;
}

@media (max-width: 560px) {
  .shell {
    padding: 32px 18px 56px;
    gap: 32px;
  }

  .brand-title {
    font-size: 28px;
  }

  .composer-button {
    width: 100%;
  }
}

