import { chromium } from 'playwright-core'
import os from 'node:os'
import path from 'node:path'

const exe = path.join(
  os.homedir(),
  'Library/Caches/ms-playwright/chromium_headless_shell-1234/chrome-headless-shell-mac-arm64/chrome-headless-shell',
)

const URL = 'http://localhost:5173'

const browser = await chromium.launch({ executablePath: exe })
const context = await browser.newContext()
const page = await context.newPage()

const bg = () => page.evaluate(() => getComputedStyle(document.body).backgroundColor)
const stored = () => page.evaluate(() => window.localStorage.getItem('kane-notes-theme'))

await page.goto(URL, { waitUntil: 'networkidle' })
await page.getByRole('heading', { name: 'Kane Notes' }).waitFor()
console.log('1. initial background      :', await bg(), '| stored:', await stored())

await page.getByRole('button', { name: 'Toggle dark mode' }).click()
await page.waitForTimeout(400)
console.log('2. after toggle            :', await bg(), '| stored:', await stored())

// Fresh load, same browser context (localStorage survives, in-memory state does not).
await page.goto(URL, { waitUntil: 'networkidle' })
await page.getByRole('heading', { name: 'Kane Notes' }).waitFor()
await page.waitForTimeout(400)
const afterReload = await bg()
console.log('3. after full reload       :', afterReload, '| stored:', await stored())

const [r, g, b] = afterReload.match(/\d+/g).map(Number)
const luminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255
console.log('\nreload background luminance:', luminance.toFixed(3))
console.log(luminance < 0.3 ? 'PASS — dark mode survived the reload' : 'FAIL — reverted to light')

await browser.close()

